/* app.css */
@import "tailwindcss";

@theme {
  --font-display: "Satoshi", ui-sans-serif, system-ui, sans-serif;

  --color-brand-50: oklch(0.97 0.02 265);
  --color-brand-500: oklch(0.60 0.20 265);
  --color-brand-900: oklch(0.30 0.12 265);

  --breakpoint-3xl: 120rem;          /* enables 3xl: */
  --radius-card: 1.25rem;            /* enables rounded-card */
  --ease-snappy: cubic-bezier(0.2, 0, 0, 1);  /* enables ease-snappy */
}

